<script setup lang="ts">
import { computed, ref } from 'vue';
import {
  Activity, ArrowDownRight, ArrowRight, ArrowUpRight, BadgePercent, Banknote, BarChart3,
  Bell, Boxes, CalendarDays, Check, CheckCircle2, Clock3, CreditCard, Download, FileText,
  Filter, Package, PackageCheck, Plus, RefreshCw, Search, ShoppingBag, Star, Tag, TrendingUp,
  Truck, Users, Wallet, X
} from 'lucide-vue-next';
import {
  demoCategoryRevenue, demoCommerceNotifications, demoCoupons, demoCustomerGrowth,
  demoInventoryMovements, demoPaymentMethods, demoRevenueBreakdown, demoReviews,
  demoSalesTrend, demoShipping, demoTopProducts, type CommerceNoticeKind
} from '../data/adminCommerceDemo';
import type { Product } from '../data/products';

export type CommerceWorkspaceSection = 'dashboard' | 'inventory' | 'sales' | 'payments' | 'discounts' | 'shipping' | 'reviews' | 'notifications' | 'reports' | 'settings';
type WorkspaceStats = { orders: number; customers: number; products: number; revenue: number };
type WorkspaceProduct = Product & { isActive?: boolean };
type WorkspaceOrder = { id: string; orderNumber: string; customerName: string; total: number; status: string; createdAt: string; payment?: { status: string; method: string; providerRef?: string | null } | null };
type WorkspaceCustomer = { id: string; createdAt?: string };

const props = defineProps<{ section: CommerceWorkspaceSection; locale: string; lightMode: boolean; stats: WorkspaceStats; products: WorkspaceProduct[]; orders: WorkspaceOrder[]; customers: WorkspaceCustomer[] }>();
const emit = defineEmits<{ navigate: [section: 'products' | 'orders' | 'customers'] }>();
const search = ref('');
const range = ref('7 days');
const inventoryFilter = ref('all');
const paymentFilter = ref('all');
const reviewFilter = ref('all');
const reviewRating = ref('all');
const notifications = ref(demoCommerceNotifications.map((item) => ({ ...item })));
const reviews = ref(demoReviews.map((item) => ({ ...item })));
const coupons = ref(demoCoupons.map((item) => ({ ...item })));
const showCouponForm = ref(false);
const couponCode = ref('');
const couponValue = ref('10');
const couponType = ref('percent');
const toastMessage = ref('');
const minStock = ref(5);
const storeNotifications = ref(true);
const autoArchive = ref(false);

const isKhmer = computed(() => props.locale === 'km');
const sectionCopy = computed(() => {
  const copy: Record<CommerceWorkspaceSection, { enTitle: string; kmTitle: string; enDescription: string; kmDescription: string; badge: string }> = {
    dashboard: { enTitle: 'Store dashboard', kmTitle: 'ផ្ទាំងគ្រប់គ្រងហាង', enDescription: 'A live view of store operations with clearly marked sample analytics.', kmDescription: 'ទិដ្ឋភាពប្រតិបត្តិការហាង និងទិន្នន័យវិភាគសាកល្បងដែលបានសម្គាល់ច្បាស់។', badge: 'LIVE TOTALS · SAMPLE TRENDS' },
    inventory: { enTitle: 'Inventory', kmTitle: 'សារពើភ័ណ្ឌ', enDescription: 'Current catalog stock is live. Movement history below is sample data.', kmDescription: 'ស្តុកទំនិញបច្ចុប្បន្នជាទិន្នន័យផ្ទាល់។ ប្រវត្តិចលនាស្តុកជាទិន្នន័យសាកល្បង។', badge: 'LIVE CATALOG · SAMPLE HISTORY' },
    sales: { enTitle: 'Sales & revenue', kmTitle: 'ការលក់ និងចំណូល', enDescription: 'Revenue breakdown and trend charts use clearly labeled sample analytics.', kmDescription: 'ការបែងចែកចំណូល និងក្រាបប្រើទិន្នន័យសាកល្បងដែលបានសម្គាល់។', badge: 'SAMPLE ANALYTICS' },
    payments: { enTitle: 'Payments', kmTitle: 'ការទូទាត់', enDescription: 'Order payment status from the store API. COD and dynamic Bakong KHQR are supported.', kmDescription: 'ស្ថានភាពទូទាត់តាម API ហាង។ គាំទ្រ COD និង Bakong KHQR ថ្មីតាមការបញ្ជាទិញ។', badge: 'LIVE ORDERS · COD + KHQR' },
    discounts: { enTitle: 'Discounts & coupons', kmTitle: 'ការបញ្ចុះតម្លៃ និងគូប៉ុង', enDescription: 'Coupon examples and changes are stored in this page only.', kmDescription: 'គូប៉ុង និងការកែប្រែត្រូវបានរក្សាទុកតែក្នុងទំព័រនេះប៉ុណ្ណោះ។', badge: 'SAMPLE DATA' },
    shipping: { enTitle: 'Shipping', kmTitle: 'ការដឹកជញ្ជូន', enDescription: 'Carrier names and tracking records are sample fulfillment data.', kmDescription: 'ឈ្មោះក្រុមហ៊ុនដឹកជញ្ជូន និងលេខតាមដានជាទិន្នន័យសាកល្បង។', badge: 'SAMPLE DATA' },
    reviews: { enTitle: 'Reviews', kmTitle: 'ការវាយតម្លៃ', enDescription: 'Moderation actions below change sample records only.', kmDescription: 'សកម្មភាពត្រួតពិនិត្យខាងក្រោមកែប្រែកំណត់ត្រាសាកល្បងប៉ុណ្ណោះ។', badge: 'SAMPLE DATA' },
    notifications: { enTitle: 'Notifications', kmTitle: 'ការជូនដំណឹង', enDescription: 'Example store and security events for the notification center.', kmDescription: 'ឧទាហរណ៍ព្រឹត្តិការណ៍ហាង និងសុវត្ថិភាពសម្រាប់មជ្ឈមណ្ឌលជូនដំណឹង។', badge: 'SAMPLE DATA' },
    reports: { enTitle: 'Reports', kmTitle: 'របាយការណ៍', enDescription: 'Exports contain sample figures and are not production reports.', kmDescription: 'ឯកសារនាំចេញមានតួលេខសាកល្បង មិនមែនជារបាយការណ៍ផលិតកម្មទេ។', badge: 'SAMPLE EXPORTS' },
    settings: { enTitle: 'Store settings', kmTitle: 'ការកំណត់ហាង', enDescription: 'These preferences are local previews and do not update the server.', kmDescription: 'ចំណូលចិត្តទាំងនេះជាការមើលសាកល្បង មិនធ្វើបច្ចុប្បន្នភាពម៉ាស៊ីនមេទេ។', badge: 'LOCAL PREVIEW' }
  };
  return copy[props.section];
});
const title = computed(() => isKhmer.value ? sectionCopy.value.kmTitle : sectionCopy.value.enTitle);
const description = computed(() => isKhmer.value ? sectionCopy.value.kmDescription : sectionCopy.value.enDescription);
const money = (value: number) => new Intl.NumberFormat(isKhmer.value ? 'km-KH' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value);
const statusCount = (status: string) => props.orders.filter((order) => order.status === status).length;
const lowStockProducts = computed(() => props.products.filter((product) => product.stock > 0 && product.stock <= minStock.value));
const outOfStockProducts = computed(() => props.products.filter((product) => product.stock <= 0));
const filteredInventory = computed(() => props.products.filter((product) => {
  const matchesSearch = `${product.nameEn} ${product.nameKm} ${product.sku}`.toLowerCase().includes(search.value.toLowerCase());
  const matchesFilter = inventoryFilter.value === 'all' || (inventoryFilter.value === 'low' && product.stock > 0 && product.stock <= minStock.value) || (inventoryFilter.value === 'out' && product.stock <= 0) || (inventoryFilter.value === 'healthy' && product.stock > minStock.value);
  return matchesSearch && matchesFilter;
}));
const filteredPayments = computed(() => props.orders.filter((order) => paymentFilter.value === 'all' || (order.payment?.status ?? 'PENDING') === paymentFilter.value));
const filteredReviews = computed(() => reviews.value.filter((review) => (reviewFilter.value === 'all' || review.status === reviewFilter.value) && (reviewRating.value === 'all' || review.rating === Number(reviewRating.value))));
const unreadCount = computed(() => notifications.value.filter((item) => !item.read).length);
const maxSales = Math.max(...demoSalesTrend.map((item) => item.sales));
const maxGrowth = Math.max(...demoCustomerGrowth.map((item) => item.customers));
const metricCards = computed(() => [
  { label: isKhmer.value ? 'សរុបការលក់' : 'Total sales', value: money(Number(props.stats.revenue)), detail: isKhmer.value ? 'សរុបពី API ហាង' : 'Live store API', icon: Wallet, tone: 'green', live: true },
  { label: isKhmer.value ? 'ការលក់ថ្ងៃនេះ' : "Today's sales", value: '$1,284', detail: isKhmer.value ? 'ទិន្នន័យសាកល្បង' : 'Sample estimate', icon: TrendingUp, tone: 'blue', live: false },
  { label: isKhmer.value ? 'ចំណូលប្រចាំខែ' : 'Monthly revenue', value: '$43,690', detail: isKhmer.value ? 'ទិន្នន័យសាកល្បង' : 'Sample analytics', icon: BarChart3, tone: 'gold', live: false },
  { label: isKhmer.value ? 'ការបញ្ជាទិញសរុប' : 'Total orders', value: String(props.stats.orders), detail: isKhmer.value ? 'គ្រប់ការបញ្ជាទិញ' : 'All-time live count', icon: ShoppingBag, tone: 'blue', live: true },
  { label: isKhmer.value ? 'កំពុងរង់ចាំ' : 'Pending orders', value: String(statusCount('PENDING')), detail: isKhmer.value ? 'ក្នុង ១០០ ចុងក្រោយ' : 'Latest 100 orders', icon: Clock3, tone: 'gold', live: true },
  { label: isKhmer.value ? 'បានបញ្ចប់' : 'Completed orders', value: String(statusCount('DELIVERED')), detail: isKhmer.value ? 'ក្នុង ១០០ ចុងក្រោយ' : 'Latest 100 orders', icon: CheckCircle2, tone: 'green', live: true },
  { label: isKhmer.value ? 'បានលុបចោល' : 'Cancelled orders', value: String(statusCount('CANCELLED')), detail: isKhmer.value ? 'ក្នុង ១០០ ចុងក្រោយ' : 'Latest 100 orders', icon: X, tone: 'red', live: true },
  { label: isKhmer.value ? 'អតិថិជនសរុប' : 'Total customers', value: String(props.stats.customers), detail: isKhmer.value ? 'គ្រប់គណនីអតិថិជន' : 'Live store API', icon: Users, tone: 'blue', live: true },
  { label: isKhmer.value ? 'អតិថិជនថ្មី' : 'New customers', value: '641', detail: isKhmer.value ? 'ខែនេះ · សាកល្បង' : 'This month · sample', icon: Users, tone: 'gold', live: false },
  { label: isKhmer.value ? 'ទំនិញ' : 'Products', value: String(props.stats.products), detail: isKhmer.value ? 'ក្នុងកាតាឡុក' : 'Live catalog count', icon: Boxes, tone: 'blue', live: true },
  { label: isKhmer.value ? 'ស្តុកទាប' : 'Low stock', value: String(lowStockProducts.value.length), detail: isKhmer.value ? `ក្រោម ${minStock.value} ឯកតា` : `At or below ${minStock.value} units`, icon: Package, tone: lowStockProducts.value.length ? 'gold' : 'green', live: true },
  { label: isKhmer.value ? 'អស់ស្តុក' : 'Out of stock', value: String(outOfStockProducts.value.length), detail: isKhmer.value ? 'សូមពិនិត្យសារពើភ័ណ្ឌ' : 'Review inventory', icon: PackageCheck, tone: outOfStockProducts.value.length ? 'red' : 'green', live: true }
]);

function notify(message: string) {
  toastMessage.value = message;
  window.setTimeout(() => { if (toastMessage.value === message) toastMessage.value = ''; }, 3000);
}

function moderateReview(review: typeof reviews.value[number], status: 'Approved' | 'Rejected') {
  review.status = status;
  notify(`${review.id} ${status.toLowerCase()} in sample data`);
}

function markRead(id: string) {
  const item = notifications.value.find((notification) => notification.id === id);
  if (item) item.read = true;
}

function markAllRead() {
  notifications.value.forEach((item) => { item.read = true; });
  notify('Sample notifications marked as read');
}

function createCoupon() {
  const normalizedCode = couponCode.value.trim().toUpperCase();
  if (!normalizedCode) return;
  if (coupons.value.some((coupon) => coupon.code === normalizedCode)) {
    notify('That sample coupon code already exists');
    return;
  }
  coupons.value.unshift({ code: normalizedCode, discount: couponType.value === 'percent' ? `${couponValue.value}%` : `$${couponValue.value}`, scope: 'Storewide', starts: 'Today', ends: 'Set in sample', uses: '0 / 100', status: 'Active' });
  couponCode.value = '';
  showCouponForm.value = false;
  notify('Sample coupon created locally');
}

function exportSampleReport(reportName: string) {
  const csv = ['Report,Value', `Source,Sample data`, `Report,${reportName}`, `Generated,${new Date().toISOString()}`].join('\r\n');
  const objectUrl = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
  const link = document.createElement('a');
  link.href = objectUrl;
  link.download = `${reportName.toLowerCase().replaceAll(' ', '-')}-sample.csv`;
  link.click();
  URL.revokeObjectURL(objectUrl);
  notify('Sample CSV downloaded; it contains no live store records');
}
</script>

<template>
  <section class="commerce-workspace" :class="{ 'commerce-light': lightMode }">
    <header class="workspace-heading"><div><span class="workspace-kicker">{{ section === 'dashboard' ? (isKhmer ? 'ប្រតិបត្តិការហាង' : 'STORE OPERATIONS') : (isKhmer ? 'ការគ្រប់គ្រងហាង' : 'COMMERCE MANAGEMENT') }}</span><h2>{{ title }}</h2><p>{{ description }}</p></div><div class="workspace-heading-actions"><span class="data-origin"><i></i>{{ sectionCopy.badge }}</span><select v-if="section === 'dashboard' || section === 'sales'" v-model="range" aria-label="Analytics date range"><option>7 days</option><option>30 days</option><option>90 days</option></select><button v-if="section === 'dashboard'" class="workspace-icon-button" type="button" aria-label="Refresh sample analytics" @click="notify('Dashboard refreshed')"><RefreshCw :size="15" /></button></div></header>
    <Transition name="workspace-toast"><div v-if="toastMessage" class="workspace-toast" role="status"><Check :size="14" />{{ toastMessage }}</div></Transition>

    <template v-if="section === 'dashboard'">
      <div class="commerce-metrics"><article v-for="metric in metricCards" :key="metric.label" class="commerce-metric" :class="`tone-${metric.tone}`"><div><span>{{ metric.label }}</span><component :is="metric.icon" :size="16" /></div><strong>{{ metric.value }}</strong><small><i v-if="metric.live"></i><span>{{ metric.detail }}</span><em v-if="!metric.live">SAMPLE</em></small></article></div>
      <div class="dashboard-charts"><section class="commerce-panel sales-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'និន្នាការការលក់ និងការបញ្ជាទិញ' : 'Sales & order trend' }}</h3><p>{{ range }} · {{ isKhmer ? 'ក្រាបសាកល្បង' : 'Sample analytics' }}</p></div><div class="chart-legend"><span><i class="legend-revenue"></i>{{ isKhmer ? 'ការលក់' : 'Sales' }}</span><span><i class="legend-orders"></i>{{ isKhmer ? 'ការបញ្ជាទិញ' : 'Orders' }}</span></div></header><div class="sales-chart"><div class="chart-y-labels"><span>$1.5k</span><span>$1k</span><span>$500</span><span>$0</span></div><div class="chart-columns"><div v-for="point in demoSalesTrend" :key="point.day" class="sales-column"><div class="sales-bars"><span class="revenue-bar" :style="{ height: `${point.sales / maxSales * 100}%` }" :title="money(point.sales)"></span><span class="orders-bar" :style="{ height: `${point.orders / 40 * 100}%` }" :title="`${point.orders} orders`"></span></div><small>{{ point.day }}</small></div></div></div></section><section class="commerce-panel category-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'ចំណូលតាមប្រភេទ' : 'Revenue by category' }}</h3><p>{{ isKhmer ? 'ចំណែកនៃចំណូលសាកល្បង' : 'Share of sample revenue' }}</p></div><Tag :size="16" /></header><div class="category-bars"><div v-for="category in demoCategoryRevenue" :key="category.name" class="category-bar-row"><div><span>{{ category.name }}</span><strong>{{ category.value }}%</strong></div><div class="category-track"><i :class="`category-${category.color}`" :style="{ width: `${category.value}%` }"></i></div><small>{{ money(category.amount) }}</small></div></div></section></div>
      <div class="dashboard-bottom"><section class="commerce-panel top-products-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'ទំនិញលក់ដាច់' : 'Top-selling products' }}</h3><p>{{ isKhmer ? 'ចំនួនលក់ និងចំណូល · សាកល្បង' : 'Units sold & revenue · sample' }}</p></div><button type="button" class="workspace-link" @click="emit('navigate', 'products')">{{ isKhmer ? 'ទំនិញទាំងអស់' : 'All products' }} <ArrowRight :size="13" /></button></header><div class="top-product-list"><article v-for="(product, index) in demoTopProducts" :key="product.sku" class="top-product-row"><span class="product-rank">0{{ index + 1 }}</span><img :src="`https://images.unsplash.com/${product.image}?auto=format&fit=crop&w=100&q=75`" :alt="isKhmer ? product.nameKm : product.nameEn" /><div><strong>{{ isKhmer ? product.nameKm : product.nameEn }}</strong><small>{{ product.sku }} · {{ product.units }} {{ isKhmer ? 'បានលក់' : 'sold' }}</small></div><b>{{ money(product.revenue) }}</b></article></div></section><div class="side-analytics"><section class="commerce-panel customer-growth-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'កំណើនអតិថិជន' : 'Customer growth' }}</h3><p>{{ isKhmer ? 'អតិថិជនថ្មី · សាកល្បង' : 'New customers · sample' }}</p></div><Users :size="16" /></header><div class="growth-chart"><div v-for="point in demoCustomerGrowth" :key="point.month" class="growth-column"><i :style="{ height: `${point.customers / maxGrowth * 100}%` }"></i><small>{{ point.month }}</small></div></div></section><section class="commerce-panel payment-mix-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'វិធីទូទាត់' : 'Payment methods' }}</h3><p>{{ isKhmer ? 'ការបែងចែកសាកល្បង' : 'Sample distribution' }}</p></div><CreditCard :size="16" /></header><div v-for="method in demoPaymentMethods" :key="method.name" class="payment-mix-row"><span><i :class="`category-${method.color}`"></i>{{ method.name }}</span><strong>{{ method.value }}%</strong></div></section></div></div>
      <div class="dashboard-footer-note"><Activity :size="13" />{{ isKhmer ? 'ចំនួនសរុបពីហាងទាញចេញពី API។ ក្រាប និងទិន្នន័យដែលមានស្លាក SAMPLE ជាឧទាហរណ៍ប៉ុណ្ណោះ។' : 'Store totals come from the live API. Charts and figures marked SAMPLE are illustrative only.' }}</div>
    </template>

    <template v-else-if="section === 'inventory'">
      <div class="inventory-kpis"><article><span>{{ isKhmer ? 'ទំនិញសរុប' : 'Catalog items' }}</span><strong>{{ products.length }}</strong></article><article><span>{{ isKhmer ? 'ស្តុកទាប' : 'Low stock' }}</span><strong class="warning-value">{{ lowStockProducts.length }}</strong></article><article><span>{{ isKhmer ? 'អស់ស្តុក' : 'Out of stock' }}</span><strong class="critical-value">{{ outOfStockProducts.length }}</strong></article><label><span>{{ isKhmer ? 'កម្រិតស្តុកទាប' : 'Low-stock threshold' }}</span><input v-model.number="minStock" type="number" min="1" max="100" /></label></div>
      <section class="commerce-panel module-table-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'ស្តុកបច្ចុប្បន្ន' : 'Current stock' }}</h3><p>{{ isKhmer ? 'ទិន្នន័យកាតាឡុកផ្ទាល់' : 'Live catalog values' }}</p></div><button class="workspace-button" type="button" @click="emit('navigate', 'products')"><Boxes :size="14" />{{ isKhmer ? 'កែទំនិញ' : 'Edit products' }}</button></header><div class="module-toolbar"><label><Search :size="14" /><input v-model="search" :placeholder="isKhmer ? 'ស្វែងរកទំនិញ...' : 'Search products...'" /></label><select v-model="inventoryFilter" aria-label="Filter inventory"><option value="all">{{ isKhmer ? 'ស្តុកទាំងអស់' : 'All stock' }}</option><option value="low">{{ isKhmer ? 'ស្តុកទាប' : 'Low stock' }}</option><option value="out">{{ isKhmer ? 'អស់ស្តុក' : 'Out of stock' }}</option><option value="healthy">{{ isKhmer ? 'ស្តុកគ្រប់គ្រាន់' : 'Healthy stock' }}</option></select></div><div class="table-scroll"><table class="commerce-table"><thead><tr><th>{{ isKhmer ? 'ទំនិញ' : 'Product' }}</th><th>SKU</th><th>{{ isKhmer ? 'ប្រភេទ' : 'Category' }}</th><th>{{ isKhmer ? 'តម្លៃ' : 'Price' }}</th><th>{{ isKhmer ? 'ស្តុក' : 'On hand' }}</th><th>{{ isKhmer ? 'ស្ថានភាព' : 'Status' }}</th></tr></thead><tbody><tr v-for="product in filteredInventory" :key="product.id"><td><div class="module-product-cell"><img v-if="product.images[0]" :src="product.images[0]" :alt="''" /><span><strong>{{ isKhmer ? product.nameKm : product.nameEn }}</strong><small>{{ product.isActive === false ? (isKhmer ? 'បានបិទ' : 'Inactive') : (isKhmer ? 'សកម្ម' : 'Active') }}</small></span></div></td><td class="code-cell">{{ product.sku }}</td><td>{{ product.category }}</td><td>{{ money(product.price) }}</td><td><strong>{{ product.stock }}</strong></td><td><span class="inventory-state" :class="product.stock <= 0 ? 'critical' : product.stock <= minStock ? 'warning' : 'healthy'"><i></i>{{ product.stock <= 0 ? (isKhmer ? 'អស់ស្តុក' : 'Out of stock') : product.stock <= minStock ? (isKhmer ? 'ស្តុកទាប' : 'Low stock') : (isKhmer ? 'គ្រប់គ្រាន់' : 'In stock') }}</span></td></tr><tr v-if="!filteredInventory.length"><td colspan="6" class="empty-row">{{ isKhmer ? 'មិនមានទំនិញដែលត្រូវគ្នាទេ។' : 'No matching products.' }}</td></tr></tbody></table></div></section>
      <section class="commerce-panel module-table-panel movement-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'ចលនាស្តុកថ្មីៗ' : 'Recent stock movements' }}</h3><p>{{ isKhmer ? 'ប្រវត្តិសាកល្បង · មិនបានរក្សាទុកនៅម៉ាស៊ីនមេ' : 'Sample history · not persisted to the server' }}</p></div><span class="sample-chip">SAMPLE</span></header><div class="table-scroll"><table class="commerce-table"><thead><tr><th>{{ isKhmer ? 'ទំនិញ' : 'Product' }}</th><th>{{ isKhmer ? 'ការផ្លាស់ប្តូរ' : 'Change' }}</th><th>{{ isKhmer ? 'មូលហេតុ' : 'Reason' }}</th><th>{{ isKhmer ? 'អ្នកធ្វើ' : 'Actor' }}</th><th>{{ isKhmer ? 'ពេលវេលា' : 'Time' }}</th></tr></thead><tbody><tr v-for="movement in demoInventoryMovements" :key="movement.id"><td><strong>{{ movement.product }}</strong><small>{{ movement.sku }}</small></td><td><span class="movement-change" :class="movement.change > 0 ? 'positive' : 'negative'">{{ movement.change > 0 ? '+' : '' }}{{ movement.change }}</span></td><td>{{ movement.reason }}</td><td>{{ movement.actor }}</td><td>{{ movement.time }}</td></tr></tbody></table></div></section>
