      <div class="commerce-panel sales-panel analytics-sales"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'ការលក់តាមពេលវេលា' : 'Sales over time' }}</h3><p>{{ range }} · {{ isKhmer ? 'ទិន្នន័យសាកល្បង' : 'Sample analytics' }}</p></div><div class="sales-filters"><select aria-label="Filter revenue by category"><option>{{ isKhmer ? 'គ្រប់ប្រភេទ' : 'All categories' }}</option><option>Home & living</option><option>Accessories</option><option>Beauty & care</option></select><select aria-label="Filter revenue by payment method"><option>{{ isKhmer ? 'គ្រប់វិធីទូទាត់' : 'All payment methods' }}</option><option>Cash on delivery</option><option>Bank transfer · sample</option></select></div></header><div class="sales-chart large-chart"><div class="chart-y-labels"><span>$1.5k</span><span>$1k</span><span>$500</span><span>$0</span></div><div class="chart-columns"><div v-for="point in demoSalesTrend" :key="point.day" class="sales-column"><div class="sales-bars"><span class="revenue-bar" :style="{ height: `${point.sales / maxSales * 100}%` }"></span><span class="orders-bar" :style="{ height: `${point.orders / 40 * 100}%` }"></span></div><small>{{ point.day }}</small></div></div></div></div>
      <div class="dashboard-charts sales-insights"><section class="commerce-panel category-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'ចំណូលតាមប្រភេទ' : 'Revenue by category' }}</h3><p>Gross sales · sample</p></div></header><div class="category-bars"><div v-for="category in demoCategoryRevenue" :key="category.name" class="category-bar-row"><div><span>{{ category.name }}</span><strong>{{ category.value }}%</strong></div><div class="category-track"><i :class="`category-${category.color}`" :style="{ width: `${category.value}%` }"></i></div><small>{{ money(category.amount) }}</small></div></div></section><section class="commerce-panel category-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'ការទូទាត់តាមវិធី' : 'Payment method mix' }}</h3><p>Share of sample transactions</p></div><CreditCard :size="16" /></header><div v-for="method in demoPaymentMethods" :key="method.name" class="payment-mix-row"><span><i :class="`category-${method.color}`"></i>{{ method.name }}</span><strong>{{ method.value }}%</strong></div></section></div>
