      <div class="payment-method-grid"><article v-for="method in demoPaymentMethods" :key="method.name" class="commerce-panel method-card"><span class="method-icon"><CreditCard :size="17" /></span><div><strong>{{ method.name }}</strong><small>{{ method.name === 'Cash on delivery' ? (isKhmer ? 'បានកំណត់រចនាសម្ព័ន្ធ' : 'Configured') : method.name.startsWith('Bakong KHQR') ? (isKhmer ? 'QR ថ្មីតាមការបញ្ជាទិញ' : 'Dynamic per-order QR') : (isKhmer ? 'មិនទាន់ភ្ជាប់' : 'Not integrated') }}</small></div><span class="method-share">{{ method.value }}%<small>SAMPLE</small></span></article></div>
      <section class="commerce-panel module-table-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'ការទូទាត់តាមការបញ្ជាទិញ' : 'Order payments' }}</h3><p>{{ isKhmer ? 'ទិន្នន័យការបញ្ជាទិញផ្ទាល់' : 'Live order records · no credentials shown' }}</p></div><select v-model="paymentFilter" aria-label="Filter payment status"><option value="all">{{ isKhmer ? 'ស្ថានភាពទាំងអស់' : 'All statuses' }}</option><option value="PENDING">Pending</option><option value="PAID">Paid</option><option value="FAILED">Failed</option><option value="REFUNDED">Refunded</option></select></header><div class="table-scroll"><table class="commerce-table"><thead><tr><th>Transaction</th><th>{{ isKhmer ? 'ការបញ្ជាទិញ' : 'Order' }}</th><th>{{ isKhmer ? 'អតិថិជន' : 'Customer' }}</th><th>{{ isKhmer ? 'ចំនួនទឹកប្រាក់' : 'Amount' }}</th><th>{{ isKhmer ? 'វិធីទូទាត់' : 'Method' }}</th><th>{{ isKhmer ? 'ស្ថានភាព' : 'Status' }}</th><th>{{ isKhmer ? 'កាលបរិច្ឆេទ' : 'Date' }}</th></tr></thead><tbody><tr v-for="order in filteredPayments.slice(0, 12)" :key="order.id"><td class="code-cell">{{ order.payment?.providerRef || 'COD · —' }}</td><td><strong>{{ order.orderNumber }}</strong></td><td>{{ order.customerName }}</td><td><strong>{{ money(Number(order.total)) }}</strong></td><td>{{ order.payment?.method || 'CASH_ON_DELIVERY' }}</td><td><span class="inventory-state" :class="(order.payment?.status || 'PENDING').toLowerCase()"><i></i>{{ order.payment?.status || 'PENDING' }}</span></td><td>{{ new Date(order.createdAt).toLocaleDateString(isKhmer ? 'km-KH' : 'en-US') }}</td></tr><tr v-if="!filteredPayments.length"><td colspan="7" class="empty-row">{{ isKhmer ? 'មិនមានប្រតិបត្តិការទេ។' : 'No matching payments.' }}</td></tr></tbody></table></div></section>
