      <section class="commerce-panel module-table-panel"><div class="table-scroll"><table class="commerce-table"><thead><tr><th>{{ isKhmer ? 'កូដ' : 'Code' }}</th><th>{{ isKhmer ? 'ការបញ្ចុះ' : 'Discount' }}</th><th>{{ isKhmer ? 'វិសាលភាព' : 'Scope' }}</th><th>{{ isKhmer ? 'កាលបរិច្ឆេទ' : 'Dates' }}</th><th>{{ isKhmer ? 'ការប្រើប្រាស់' : 'Usage' }}</th><th>{{ isKhmer ? 'ស្ថានភាព' : 'Status' }}</th></tr></thead><tbody><tr v-for="coupon in coupons" :key="coupon.code"><td><span class="coupon-code"><Tag :size="13" />{{ coupon.code }}</span></td><td><strong>{{ coupon.discount }}</strong></td><td>{{ coupon.scope }}</td><td>{{ coupon.starts }} – {{ coupon.ends }}</td><td>{{ coupon.uses }}</td><td><span class="inventory-state" :class="coupon.status === 'Active' ? 'healthy' : 'neutral'"><i></i>{{ coupon.status }}</span></td></tr></tbody></table></div></section>
