      <section class="commerce-panel module-table-panel"><header class="commerce-panel-heading"><div><h3>{{ isKhmer ? 'ការដឹកជញ្ជូនថ្មីៗ' : 'Recent shipments' }}</h3><p>{{ isKhmer ? 'ព័ត៌មានក្រុមហ៊ុន និងតាមដានជាគំរូ' : 'Carrier and tracking information are sample records' }}</p></div><Filter :size="16" /></header><div class="table-scroll"><table class="commerce-table"><thead><tr><th>{{ isKhmer ? 'ការបញ្ជាទិញ' : 'Order' }}</th><th>{{ isKhmer ? 'អតិថិជន' : 'Customer' }}</th><th>{{ isKhmer ? 'ក្រុមហ៊ុន' : 'Carrier' }}</th><th>{{ isKhmer ? 'លេខតាមដាន' : 'Tracking number' }}</th><th>{{ isKhmer ? 'តំបន់' : 'Zone' }}</th><th>{{ isKhmer ? 'ETA' : 'ETA' }}</th><th>{{ isKhmer ? 'ស្ថានភាព' : 'Status' }}</th></tr></thead><tbody><tr v-for="shipment in demoShipping" :key="shipment.order"><td><strong>{{ shipment.order }}</strong></td><td>{{ shipment.customer }}</td><td>{{ shipment.provider }}</td><td class="code-cell">{{ shipment.tracking }}</td><td>{{ shipment.zone }}</td><td>{{ shipment.eta }}</td><td><span class="inventory-state" :class="shipment.status === 'Delivered' ? 'healthy' : 'warning'"><i></i>{{ shipment.status }}</span></td></tr></tbody></table></div></section>
      <section class="commerce-panel zones-panel"><div><Truck :size="16" /><strong>{{ isKhmer ? 'តំបន់ និងថ្លៃដឹកជញ្ជូន' : 'Delivery zones & rates' }}</strong></div><span>Phnom Penh · $2.00</span><span>Provincial cities · $3.50</span><span>Remote areas · $5.00</span><small>SAMPLE SHIPPING CONFIGURATION</small></section>
