      <div class="review-list"><article v-for="review in filteredReviews" :key="review.id" class="commerce-panel review-card"><div class="review-avatar">{{ review.customer.split(' ').map((part) => part[0]).join('') }}</div><div class="review-copy"><header><div><strong>{{ review.customer }}</strong><small>{{ review.product }} · {{ review.date }}</small></div><span class="review-rating"><Star v-for="star in 5" :key="star" :size="12" :fill="star <= review.rating ? 'currentColor' : 'none'" />{{ review.rating }}</span></header><p>{{ review.text }}</p><span class="inventory-state" :class="review.status === 'Approved' ? 'healthy' : review.status === 'Reported' ? 'critical' : 'warning'"><i></i>{{ review.status }}</span></div><div v-if="review.status === 'Pending' || review.status === 'Reported'" class="review-actions"><button type="button" class="approve-review" @click="moderateReview(review, 'Approved')"><Check :size="13" />{{ isKhmer ? 'អនុម័ត' : 'Approve' }}</button><button type="button" class="reject-review" @click="moderateReview(review, 'Rejected')"><X :size="13" />{{ isKhmer ? 'បដិសេធ' : 'Reject' }}</button></div></article><div v-if="!filteredReviews.length" class="commerce-panel empty-module">{{ isKhmer ? 'មិនមានការវាយតម្លៃទេ។' : 'No reviews match these filters.' }}</div></div>
