    <template v-else-if="section === 'notifications'">
      <div class="module-action-row"><p>{{ isKhmer ? `${unreadCount} ការជូនដំណឹងមិនទាន់អាន` : `${unreadCount} unread notifications` }}</p><button class="workspace-button" type="button" @click="markAllRead"><Check :size="14" />{{ isKhmer ? 'សម្គាល់ថាអានទាំងអស់' : 'Mark all as read' }}</button></div><div class="notification-list"><article v-for="notification in notifications" :key="notification.id" class="commerce-panel notification-row" :class="{ unread: !notification.read }"><span class="notification-icon" :class="`notice-${notification.kind.toLowerCase()}`"><ShoppingBag v-if="notification.kind === 'Order'" :size="16" /><Banknote v-else-if="notification.kind === 'Payment'" :size="16" /><Boxes v-else-if="notification.kind === 'Inventory'" :size="16" /><Users v-else-if="notification.kind === 'Customer'" :size="16" /><Star v-else-if="notification.kind === 'Review'" :size="16" /><Activity v-else :size="16" /></span><div><strong>{{ notification.title }}</strong><p>{{ notification.description }}</p><small>{{ notification.id }} · {{ notification.time }}</small></div><span v-if="!notification.read" class="unread-dot" aria-label="Unread"></span><button v-if="!notification.read" class="workspace-link" type="button" @click="markRead(notification.id)">{{ isKhmer ? 'អាន' : 'Mark read' }}</button><Check v-else class="read-check" :size="15" /></article></div>
